import{_ as e,o,c,a5 as a}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"Sequence Flow — Two-Factor Authentication (2FA, TOTP)","description":"","frontmatter":{},"headers":[],"relativePath":"feature/authentication/3-2-7-two-factor-authentication-2fa-totp/sequence-flow.md","filePath":"feature/authentication/3-2-7-two-factor-authentication-2fa-totp/sequence-flow.md"}'),i={name:"feature/authentication/3-2-7-two-factor-authentication-2fa-totp/sequence-flow.md"};function r(n,t,d,s,l,u){return o(),c("div",null,[...t[0]||(t[0]=[a('<h1 id="sequence-flow-—-two-factor-authentication-2fa-totp" tabindex="-1">Sequence Flow — Two-Factor Authentication (2FA, TOTP) <a class="header-anchor" href="#sequence-flow-—-two-factor-authentication-2fa-totp" aria-label="Permalink to &quot;Sequence Flow — Two-Factor Authentication (2FA, TOTP)&quot;">​</a></h1><p>&gt; Supplements <code>spec.md</code> (FR 3.2.7). This file lists each step as actor → action → system, in enough detail to draw the sequence diagram directly — it does not restate business rules (see spec.md for those).</p><h2 id="actors" tabindex="-1">Actors <a class="header-anchor" href="#actors" aria-label="Permalink to &quot;Actors&quot;">​</a></h2><ul><li><strong>User</strong> — actor tương tác chính trong quy trình.</li><li><strong>Client</strong> — giao diện người dùng <code>SecuritySettingsPage (UI)</code>.</li><li><strong>System</strong> — <code>AuthController</code> / <code>AuthService</code>.</li></ul><hr><h2 id="flow-a-—-luong-thuc-thi-chinh-two-factor-authentication-2fa-totp" tabindex="-1">Flow A — Luồng thực thi chính: Two-Factor Authentication (2FA, TOTP) <a class="header-anchor" href="#flow-a-—-luong-thuc-thi-chinh-two-factor-authentication-2fa-totp" aria-label="Permalink to &quot;Flow A — Luồng thực thi chính: Two-Factor Authentication (2FA, TOTP)&quot;">​</a></h2><ol><li>user -&gt; securitysettingspage: <code>clicks &quot;Enable 2FA&quot;</code></li><li>securitysettingspage -&gt; authcontroller: <code>POST /api/v1/auth/2fa/setup (headers: Bearer accessToken)</code></li><li>authcontroller -&gt; authservice: <code>setup2FA(userId)</code></li><li>authservice -&gt; authenticatorapp: <code>generateSecret() -&gt; otpAuthUrl</code></li><li>authenticatorapp --&gt; authservice: <code>otpAuthUrl (QR code URL)</code></li><li>authservice -&gt; rediscache: <code>set(&quot;2fa:pending:&quot; + userId, secret, 10 min)</code></li><li>rediscache --&gt; authservice: <code>ok</code></li><li>authservice --&gt; authcontroller: <code>200 OK (otpAuthUrl)</code></li><li>authcontroller --&gt; securitysettingspage: <code>200 OK (otpAuthUrl)</code></li><li>securitysettingspage --&gt; user: <code>Display QR code to scan in Authenticator App</code></li><li>user -&gt; securitysettingspage: <code>scans QR, enters TOTP code, clicks &quot;Confirm&quot;</code></li><li>securitysettingspage -&gt; authcontroller: <code>POST /api/v1/auth/2fa/confirm (code, headers: Bearer accessToken)</code></li><li>authcontroller -&gt; authservice: <code>confirm2FA(userId, code)</code></li><li>authservice -&gt; rediscache: <code>get(&quot;2fa:pending:&quot; + userId)</code></li><li>rediscache --&gt; authservice: <code>pendingSecret</code></li><li>authservice --&gt; authcontroller: <code>400 Bad Request (TWO_FA_CODE_INVALID)</code></li><li>authcontroller --&gt; securitysettingspage: <code>400 Bad Request</code></li><li>securitysettingspage --&gt; user: <code>Show error &quot;Invalid TOTP code&quot;</code></li><li>authservice -&gt; userrepository: <code>save(user with twoFaEnabled=true, twoFaSecret)</code></li><li>userrepository --&gt; authservice: <code>ok</code></li><li>authservice -&gt; rediscache: <code>delete(&quot;2fa:pending:&quot; + userId)</code></li><li>rediscache --&gt; authservice: <code>ok</code></li><li>authservice --&gt; authcontroller: <code>200 OK</code></li><li>authcontroller --&gt; securitysettingspage: <code>200 OK</code></li><li>securitysettingspage --&gt; user: <code>&quot;Two-factor authentication enabled&quot;</code></li></ol><hr><h2 id="error-paths" tabindex="-1">Error paths <a class="header-anchor" href="#error-paths" aria-label="Permalink to &quot;Error paths&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Failure condition</th><th>HTTP</th><th>ErrorCode</th></tr></thead><tbody><tr><td>Xác thực</td><td>Token thiếu, hết hạn hoặc không hợp lệ</td><td>401</td><td><code>UNAUTHORIZED</code></td></tr><tr><td>Phân quyền</td><td>Vai trò người dùng không có quyền truy cập tính năng</td><td>403</td><td><code>FORBIDDEN</code></td></tr><tr><td>Kiểm tra dữ liệu</td><td>Dữ liệu đầu vào không hợp lệ hoặc xung đột trạng thái</td><td>400</td><td><code>BAD_REQUEST</code></td></tr><tr><td>Truy vấn</td><td>Không tìm thấy bản ghi đối tượng tương ứng</td><td>404</td><td><code>NOT_FOUND</code></td></tr></tbody></table>',10)])])}const p=e(i,[["render",r]]);export{g as __pageData,p as default};
